//! Event routing between the C# bridge and a [`Mod`] implementation.

use std::{
    panic::{catch_unwind, AssertUnwindSafe},
    sync::{
        atomic::{AtomicBool, Ordering},
        Mutex, OnceLock,
    },
};

use serde_json::{json, Value};

use crate::{
    abi::{Buf, HostApi},
    context::Context,
    host,
    traits::Mod,
    types::{MapInfo, PatchCall},
};

/// Holds the lazily created module instance of one cdylib. Generated by [`crate::export_mod!`].
pub struct ModuleCell<M> {
    instance: OnceLock<Mutex<M>>,
    initialized: AtomicBool,
}

impl<M> Default for ModuleCell<M> {
    fn default() -> Self {
        Self::new()
    }
}

impl<M> ModuleCell<M> {
    pub const fn new() -> ModuleCell<M> {
        ModuleCell { instance: OnceLock::new(), initialized: AtomicBool::new(false) }
    }
}

/// Stores the host table. Returns `0` on success.
///
/// # Safety
///
/// `host_api` must point to a table that stays alive for the whole process.
pub unsafe fn initialize(host_api: *const HostApi) -> u32 {
    if host_api.is_null() {
        return 1;
    }

    match host::install(&*host_api) {
        Ok(()) => 0,
        Err(_) => 2,
    }
}

/// Handles one event from the bridge.
///
/// Writes the JSON response buffer into `response_out` (release it with `rwrs_free_buf`) and
/// returns `0`, or returns a non-zero code when `response_out` is null.
///
/// # Safety
///
/// The pointers must describe valid buffers for the duration of the call; `response_out` must
/// be writable.
pub unsafe fn dispatch<M: Mod>(
    cell: &'static ModuleCell<M>,
    event_ptr: *const u8,
    event_len: u32,
    payload_ptr: *const u8,
    payload_len: u32,
    response_out: *mut Buf,
) -> u32 {
    if response_out.is_null() {
        return 1;
    }

    let event = read_string(event_ptr, event_len);
    let payload = read_bytes(payload_ptr, payload_len);

    let response = match catch_unwind(AssertUnwindSafe(|| run::<M>(cell, &event, &payload))) {
        Ok(response) => response,
        Err(panic) => {
            let message = panic_message(&panic);
            let _ = host::call("log", json!({ "level": "error", "message": format!("panic in Rust mod: {message}") }));
            json!({ "ok": false, "error": format!("panic: {message}") }).to_string()
        }
    };

    *response_out = Buf::from_bytes(response.into_bytes());
    0
}

fn run<M: Mod>(cell: &'static ModuleCell<M>, event: &str, payload: &[u8]) -> String {
    let mutex = cell.instance.get_or_init(|| Mutex::new(M::default()));
    let mut guard = match mutex.lock() {
        Ok(guard) => guard,
        Err(poisoned) => poisoned.into_inner(),
    };
    let module = &mut *guard;
    let ctx = &mut Context::new();

    if !cell.initialized.swap(true, Ordering::SeqCst) {
        module.on_init(ctx);
    }

    let value: Value =
        if payload.is_empty() { Value::Null } else { serde_json::from_slice(payload).unwrap_or(Value::Null) };

    match event {
        "mod_loaded" => ok(),
        "defs_loaded" => {
            module.on_defs_loaded(ctx);
            ok()
        }
        "game_started" => {
            module.on_game_started(ctx);
            ok()
        }
        "game_loaded" => {
            module.on_game_loaded(ctx);
            ok()
        }
        "game_ready" => {
            module.on_game_ready(ctx);
            ok()
        }
        "world_ready" => {
            if let Some(world) = event_payload::<crate::WorldInfo>(ctx, value) {
                module.on_world_ready(ctx, &world);
            }
            ok()
        }
        "map_ready" => {
            if let Some(map) = event_payload::<MapInfo>(ctx, value) {
                module.on_map_ready(ctx, &map);
            }
            ok()
        }
        "game_saving" => {
            module.on_game_saving(ctx);
            ok()
        }
        "game_saved" => {
            module.on_game_saved(ctx);
            ok()
        }
        "tick" => {
            module.on_tick(ctx);
            ok()
        }
        "map_generated" => {
            if let Some(map) = event_payload::<MapInfo>(ctx, value) {
                module.on_map_generated(ctx, &map);
            }
            ok()
        }
        "map_removed" => {
            let map_id = value.get("id").and_then(Value::as_i64).unwrap_or(-1) as i32;
            module.on_map_removed(ctx, map_id);
            ok()
        }
        "pawn_spawned" => {
            if let Some(handle) = value.get("pawn").and_then(crate::ObjRef::from_value) {
                let respawning = value.get("respawningAfterLoad").and_then(Value::as_bool).unwrap_or(false);
                let pawn = crate::Pawn::new(ctx, handle);
                module.on_pawn_spawned(ctx, &pawn, respawning);
            }
            ok()
        }
        "pawn_died" => {
            if let Some(info) = event_payload::<crate::PawnDied>(ctx, value) {
                module.on_pawn_died(ctx, &info);
            }
            ok()
        }
        "thing_destroyed" => {
            if let Some(info) = event_payload::<crate::ThingDestroyed>(ctx, value) {
                module.on_thing_destroyed(ctx, &info);
            }
            ok()
        }
        "bill_completed" => {
            if let Some(info) = event_payload::<crate::BillCompleted>(ctx, value) {
                module.on_bill_completed(ctx, &info);
            }
            ok()
        }
        "bill_started" => {
            if let Some(info) = event_payload::<crate::BillStarted>(ctx, value) {
                module.on_bill_started(ctx, &info);
            }
            ok()
        }
        "pawn_damaged" => {
            if let Some(info) = event_payload::<crate::PawnDamaged>(ctx, value) {
                module.on_pawn_damaged(ctx, &info);
            }
            ok()
        }
        "research_finished" => {
            if let Some(info) = event_payload::<crate::ResearchFinished>(ctx, value) {
                module.on_research_finished(ctx, &info);
            }
            ok()
        }
        "letter_shown" => {
            if let Some(info) = event_payload::<crate::LetterShown>(ctx, value) {
                module.on_letter_shown(ctx, &info);
            }
            ok()
        }
        "incident_fired" => {
            if let Some(info) = event_payload::<crate::IncidentFired>(ctx, value) {
                module.on_incident_fired(ctx, &info);
            }
            ok()
        }
        "raid_started" => {
            if let Some(info) = event_payload::<crate::RaidStarted>(ctx, value) {
                module.on_raid_started(ctx, &info);
            }
            ok()
        }
        "lord_destroyed" => {
            if let Some(info) = event_payload::<crate::LordDestroyed>(ctx, value) {
                module.on_lord_destroyed(ctx, &info);
            }
            ok()
        }
        "research_started" => {
            if let Some(info) = event_payload::<crate::ResearchStarted>(ctx, value) {
                module.on_research_started(ctx, &info);
            }
            ok()
        }
        "pawn_down" => {
            if let Some(info) = event_payload::<crate::PawnDown>(ctx, value) {
                module.on_pawn_down(ctx, &info);
            }
            ok()
        }
        "building_completed" => {
            if let Some(info) = event_payload::<crate::BuildingCompleted>(ctx, value) {
                module.on_building_completed(ctx, &info);
            }
            ok()
        }
        "quest_ended" => {
            if let Some(info) = event_payload::<crate::QuestEnded>(ctx, value) {
                module.on_quest_ended(ctx, &info);
            }
            ok()
        }
        "message_shown" => {
            if let Some(info) = event_payload::<crate::MessageShown>(ctx, value) {
                module.on_message_shown(ctx, &info);
            }
            ok()
        }
        "mental_state_started" => {
            if let Some(info) = event_payload::<crate::MentalStateStarted>(ctx, value) {
                module.on_mental_state_started(ctx, &info);
            }
            ok()
        }
        "mental_state_ended" => {
            if let Some(info) = event_payload::<crate::MentalStateEnded>(ctx, value) {
                module.on_mental_state_ended(ctx, &info);
            }
            ok()
        }
        "patch" => {
            let call = PatchCall::from_value(&value);
            module.on_patch_call(ctx, &call).to_json()
        }
        "redirect" => {
            let call = crate::RedirectCall::from_value(&value);
            match module.on_redirect_call(ctx, &call) {
                Some(result) => json!({ "ok": true, "result": result }).to_string(),
                None => ok(),
            }
        }
        "ui_action" => {
            let action = crate::UiAction::from_value(&value);
            module.on_ui_action(ctx, &action);
            ok()
        }
        "gizmos" => {
            let declared = match value.get("thing").and_then(crate::ObjRef::from_value) {
                Some(handle) => {
                    let thing = crate::Thing::new(ctx, handle);
                    serde_json::to_value(module.on_gizmos(ctx, &thing)).unwrap_or(Value::Array(Vec::new()))
                }
                None => Value::Array(Vec::new()),
            };
            json!({ "ok": true, "result": declared }).to_string()
        }
        "comp_spawned" | "comp_despawned" | "comp_tick" => {
            if let Some(comp) = crate::ThingComp::from_payload(ctx, &value) {
                match event {
                    "comp_spawned" => module.on_comp_spawned(ctx, &comp),
                    "comp_despawned" => module.on_comp_despawned(ctx, &comp),
                    _ => module.on_comp_tick(ctx, &comp),
                }
            }
            ok()
        }
        "comp_gizmos" => {
            let declared = match crate::ThingComp::from_payload(ctx, &value) {
                Some(comp) => {
                    serde_json::to_value(module.on_comp_gizmos(ctx, &comp)).unwrap_or(Value::Array(Vec::new()))
                }
                None => Value::Array(Vec::new()),
            };
            json!({ "ok": true, "result": declared }).to_string()
        }
        "comp_inspect" => {
            let text = crate::ThingComp::from_payload(ctx, &value).and_then(|comp| module.on_comp_inspect(ctx, &comp));
            json!({ "ok": true, "result": text }).to_string()
        }
        "draw" => {
            let map_id = value.get("mapId").and_then(Value::as_i64).unwrap_or(-1) as i32;
            module.on_draw(ctx, map_id);
            ok()
        }
        "settings_changed" => {
            let key = value.get("key").and_then(Value::as_str).unwrap_or_default().to_string();
            let changed = value.get("value").and_then(Value::as_str).unwrap_or_default().to_string();
            module.on_settings_changed(ctx, &key, &changed);
            ok()
        }
        "companion_event" => {
            let source = value.get("source").and_then(Value::as_str).unwrap_or_default().to_string();
            let name = value.get("name").and_then(Value::as_str).unwrap_or_default().to_string();
            let payload = value.get("payload").cloned().unwrap_or(Value::Null);
            match module.on_companion_event(ctx, &source, &name, &payload) {
                Some(answer) => json!({ "ok": true, "result": answer }).to_string(),
                None => ok(),
            }
        }
        other => json!({ "ok": false, "error": format!("unknown event '{other}'") }).to_string(),
    }
}

fn ok() -> String {
    "{\"ok\":true}".to_string()
}

/// Reads one event payload. A shape the SDK does not know used to skip the handler in silence — an
/// event that never arrives is exactly the class of bug this SDK exists to prevent (the bridge and the
/// SDK can drift), so it is logged with the type it failed to fill.
fn event_payload<T: serde::de::DeserializeOwned>(ctx: &mut Context, value: Value) -> Option<T> {
    match serde_json::from_value::<T>(value) {
        Ok(parsed) => Some(parsed),
        Err(error) => {
            ctx.warn(format!("the payload of an event did not fit {}: {error}", std::any::type_name::<T>()));
            None
        }
    }
}

unsafe fn read_bytes(ptr: *const u8, len: u32) -> Vec<u8> {
    if ptr.is_null() || len == 0 {
        Vec::new()
    } else {
        std::slice::from_raw_parts(ptr, len as usize).to_vec()
    }
}

unsafe fn read_string(ptr: *const u8, len: u32) -> String {
    String::from_utf8_lossy(&read_bytes(ptr, len)).into_owned()
}

fn panic_message(panic: &Box<dyn std::any::Any + Send>) -> String {
    if let Some(message) = panic.downcast_ref::<&str>() {
        (*message).to_string()
    } else if let Some(message) = panic.downcast_ref::<String>() {
        message.clone()
    } else {
        "unknown panic".to_string()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::{
        abi::HostApi,
        host::tests::{calls, mock_host},
        types::PatchOutcome,
    };

    #[derive(Default)]
    struct TestMod {
        inits: u32,
        ticks: u32,
    }

    impl Mod for TestMod {
        fn on_init(&mut self, ctx: &mut Context) {
            self.inits += 1;
            ctx.log("init");
        }

        fn on_tick(&mut self, ctx: &mut Context) {
            self.ticks += 1;
            let info = ctx.game_info().expect("game info");
            assert_eq!(info.tick, 1234);
            assert_eq!(info.maps.len(), 1);
        }

        fn on_patch_call(&mut self, _ctx: &mut Context, call: &PatchCall) -> PatchOutcome {
            assert_eq!(call.handler, "on_damage");
            assert_eq!(call.args.len(), 2);
            PatchOutcome::default().set_arg(0, 25).with_result("patched")
        }

        fn on_comp_spawned(&mut self, ctx: &Context, comp: &crate::ThingComp<'_>) {
            assert_eq!(comp.key(), "Steel");
            ctx.log("comp spawned");
        }

        fn on_comp_inspect(&mut self, _ctx: &Context, _comp: &crate::ThingComp<'_>) -> Option<String> {
            Some("inspected".to_string())
        }

        fn on_pawn_spawned(&mut self, ctx: &Context, pawn: &crate::Pawn<'_>, respawning_after_load: bool) {
            assert!(!respawning_after_load);
            assert_eq!(pawn.handle().id, 7);
            ctx.log("pawn spawned");
        }

        fn on_pawn_died(&mut self, _ctx: &mut Context, info: &crate::PawnDied) {
            assert_eq!(info.label.as_deref(), Some("Mock"));
            assert_eq!(info.killer_def_name.as_deref(), Some("Gun"));
            assert!(info.pawn.is_some());
        }

        fn on_thing_destroyed(&mut self, _ctx: &mut Context, info: &crate::ThingDestroyed) {
            assert_eq!(info.def_name.as_deref(), Some("Steel"));
            assert_eq!(info.mode.as_deref(), Some("Vanish"));
            assert_eq!(info.z, 20);
        }

        fn on_research_finished(&mut self, _ctx: &mut Context, info: &crate::ResearchFinished) {
            assert_eq!(info.def_name.as_deref(), Some("Smithing"));
            assert!(info.project.is_some());
        }

        fn on_letter_shown(&mut self, _ctx: &mut Context, info: &crate::LetterShown) {
            assert_eq!(info.label.as_deref(), Some("Rust API self-test"));
        }

        fn on_incident_fired(&mut self, _ctx: &mut Context, info: &crate::IncidentFired) {
            assert_eq!(info.def_name.as_deref(), Some("RaidEnemy"));
            assert!(info.fired);
        }

        fn on_raid_started(&mut self, _ctx: &mut Context, info: &crate::RaidStarted) {
            assert_eq!(info.map, 1);
            assert_eq!(info.job.as_deref(), Some("LordJob_AssaultColony"));
        }

        fn on_lord_destroyed(&mut self, _ctx: &mut Context, info: &crate::LordDestroyed) {
            assert_eq!(info.map, 1);
            assert_eq!(info.job.as_deref(), Some("LordJob_AssaultColony"));
        }

        fn on_research_started(&mut self, _ctx: &mut Context, info: &crate::ResearchStarted) {
            assert_eq!(info.def_name.as_deref(), Some("Smithing"));
        }

        fn on_pawn_down(&mut self, _ctx: &mut Context, info: &crate::PawnDown) {
            assert!(info.downed);
            assert_eq!(info.label.as_deref(), Some("Feeb"));
        }

        fn on_building_completed(&mut self, _ctx: &mut Context, info: &crate::BuildingCompleted) {
            assert_eq!(info.def_name.as_deref(), Some("Wall"));
            assert_eq!(info.map_id, 1);
        }

        fn on_quest_ended(&mut self, _ctx: &mut Context, info: &crate::QuestEnded) {
            assert_eq!(info.name.as_deref(), Some("The Mockers"));
            assert_eq!(info.outcome.as_deref(), Some("Success"));
            assert_eq!(info.state.as_deref(), Some("Ended"));
        }

        fn on_message_shown(&mut self, _ctx: &mut Context, info: &crate::MessageShown) {
            assert_eq!(info.text.as_deref(), Some("a message"));
            assert_eq!(info.def_name.as_deref(), Some("NeutralEvent"));
            assert!(!info.historical);
        }

        fn on_mental_state_started(&mut self, _ctx: &mut Context, info: &crate::MentalStateStarted) {
            assert!(info.pawn.is_some());
            assert_eq!(info.def_name.as_deref(), Some("Berserk"));
            assert!(info.forced);
        }

        fn on_mental_state_ended(&mut self, _ctx: &mut Context, info: &crate::MentalStateEnded) {
            assert_eq!(info.label.as_deref(), Some("Mock"));
        }
    }

    fn install_mock_host() {
        static API: HostApi = HostApi { user_data: core::ptr::null_mut(), call: Some(mock_host) };
        let _ = unsafe { initialize(&API) };
    }

    fn static_cell() -> &'static ModuleCell<TestMod> {
        static CELL: ModuleCell<TestMod> = ModuleCell::new();
        &CELL
    }

    /// A cell of its own, for the test that asserts on `on_init`: the shared cell may already have been
    /// initialized by whichever test ran first, and then the init callback never runs again.
    fn fresh_cell() -> &'static ModuleCell<TestMod> {
        static FRESH: ModuleCell<TestMod> = ModuleCell::new();
        &FRESH
    }

    fn send(event: &str, payload: &str) -> String {
        send_with(static_cell(), event, payload)
    }

    fn send_with(cell: &'static ModuleCell<TestMod>, event: &str, payload: &str) -> String {
        let mut buffer = crate::abi::Buf::EMPTY;
        let code = unsafe {
            dispatch::<TestMod>(
                cell,
                event.as_ptr(),
                event.len() as u32,
                payload.as_ptr(),
                payload.len() as u32,
                &mut buffer,
            )
        };
        assert_eq!(code, 0);
        let text = String::from_utf8(unsafe { buffer.as_slice() }.to_vec()).unwrap();
        unsafe { buffer.free() };
        text
    }

    #[test]
    fn dispatches_events_and_calls_handlers_once() {
        install_mock_host();
        let before = calls();
        let cell = fresh_cell();

        let response = send_with(cell, "mod_loaded", "{}");
        assert!(response.contains("\"ok\":true"));
        assert_eq!(calls(), before + 1, "on_init logs once");

        send_with(cell, "tick", "{\"tick\":1234}");
        send_with(cell, "tick", "{\"tick\":1235}");

        let patch = send_with(
            cell,
            "patch",
            "{\"handler\":\"on_damage\",\"kind\":\"prefix\",\"target\":\"T.M()\",\"args\":[10,{\"$ref\":0,\"$type\":\"X\"}]}",
        );
        assert!(patch.contains("\"skipOriginal\":false"));
        assert!(patch.contains("\"result\":\"patched\""));
        assert!(patch.contains("\"0\":25"));
    }

    #[test]
    fn unknown_events_report_an_error() {
        install_mock_host();
        let response = send("nonsense", "{}");
        assert!(response.contains("\"ok\":false"));
    }

    #[test]
    fn routes_comp_events() {
        install_mock_host();
        let payload =
            "{\"thing\":{\"$ref\":1,\"$type\":\"Steel\"},\"comp\":{\"$ref\":2,\"$type\":\"RustThingComp\"},\"key\":\"Steel\",\"respawning\":false}";

        // The handler asserts the key it was given, so a routing mistake fails the response.
        let spawned = send("comp_spawned", payload);
        assert!(spawned.contains("\"ok\":true"), "{spawned}");

        let tick = send("comp_tick", payload);
        assert!(tick.contains("\"ok\":true"), "a comp without a tick handler still answers");

        let despawned = send("comp_despawned", payload);
        assert!(despawned.contains("\"ok\":true"), "{despawned}");

        let inspect = send("comp_inspect", payload);
        assert!(inspect.contains("\"result\":\"inspected\""), "{inspect}");

        let gizmos = send("comp_gizmos", payload);
        assert!(gizmos.contains("\"result\":[]"), "{gizmos}");

        let missing = send("comp_gizmos", "{}");
        assert!(missing.contains("\"result\":[]"), "a payload without handles declares nothing");
    }

    #[test]
    fn routes_game_state_events() {
        install_mock_host();

        // The handlers assert the payload they were given, so a routing mistake fails the response.
        let pawn = "{\"$ref\":7,\"$type\":\"Verse.Pawn\",\"$str\":\"Mock\"}";
        let spawned = send("pawn_spawned", &format!("{{\"pawn\":{pawn},\"respawningAfterLoad\":false}}"));
        assert!(spawned.contains("\"ok\":true"), "{spawned}");

        let died = send(
            "pawn_died",
            &format!(
                "{{\"pawn\":{pawn},\"killer\":{{\"$ref\":8,\"$type\":\"Verse.Thing\"}},\"defName\":\"Colonist\",\"label\":\"Mock\",\"killerDefName\":\"Gun\"}}"
            ),
        );
        assert!(died.contains("\"ok\":true"), "{died}");

        let destroyed = send(
            "thing_destroyed",
            "{\"defName\":\"Steel\",\"label\":\"steel\",\"mode\":\"Vanish\",\"mapId\":1,\"x\":20,\"z\":20}",
        );
        assert!(destroyed.contains("\"ok\":true"), "{destroyed}");

        let research = send(
            "research_finished",
            "{\"project\":{\"$ref\":9,\"$type\":\"RimWorld.ResearchProjectDef\"},\"defName\":\"Smithing\",\"label\":\"Smithing\",\"researcher\":{\"$ref\":7,\"$type\":\"Verse.Pawn\"}}",
        );
        assert!(research.contains("\"ok\":true"), "{research}");

        let letter = send(
            "letter_shown",
            "{\"defName\":\"PositiveEvent\",\"label\":\"Rust API self-test\",\"text\":\"all good\"}",
        );
        assert!(letter.contains("\"ok\":true"), "{letter}");

        let incident = send("incident_fired", "{\"defName\":\"RaidEnemy\",\"label\":\"Raid\",\"fired\":true}");
        assert!(incident.contains("\"ok\":true"), "{incident}");

        let raid = send("raid_started", "{\"map\":1,\"job\":\"LordJob_AssaultColony\"}");
        assert!(raid.contains("\"ok\":true"), "{raid}");

        let gone = send("lord_destroyed", "{\"map\":1,\"job\":\"LordJob_AssaultColony\"}");
        assert!(gone.contains("\"ok\":true"), "{gone}");

        let started = send("research_started", "{\"defName\":\"Smithing\",\"label\":\"Smithing\"}");
        assert!(started.contains("\"ok\":true"), "{started}");

        let down =
            send("pawn_down", "{\"pawn\":{\"$ref\":7,\"$type\":\"Verse.Pawn\"},\"label\":\"Feeb\",\"downed\":true}");
        assert!(down.contains("\"ok\":true"), "{down}");

        let built = send(
            "building_completed",
            "{\"label\":\"wall\",\"defName\":\"Wall\",\"mapId\":1,\"x\":10,\"z\":10,\"worker\":{\"$ref\":7,\"$type\":\"Verse.Pawn\"}}",
        );
        assert!(built.contains("\"ok\":true"), "{built}");

        let quest =
            send("quest_ended", "{\"questId\":7,\"name\":\"The Mockers\",\"outcome\":\"Success\",\"state\":\"Ended\"}");
        assert!(quest.contains("\"ok\":true"), "{quest}");

        let message =
            send("message_shown", "{\"text\":\"a message\",\"defName\":\"NeutralEvent\",\"historical\":false}");
        assert!(message.contains("\"ok\":true"), "{message}");

        let started = send(
            "mental_state_started",
            &format!("{{\"pawn\":{pawn},\"label\":\"Mock\",\"defName\":\"Berserk\",\"forced\":true}}"),
        );
        assert!(started.contains("\"ok\":true"), "{started}");

        let ended =
            send("mental_state_ended", &format!("{{\"pawn\":{pawn},\"label\":\"Mock\",\"defName\":\"Berserk\"}}"));
        assert!(ended.contains("\"ok\":true"), "{ended}");
    }
}
